function assetRequest(asset){
 if(asset==='index.html')return new URL('./',self.registration.scope).href;
 if(asset==='update.html')return new URL('update',self.registration.scope).href;
 return new URL(asset,self.registration.scope).href;
}
function assetKey(asset,url){return asset==='index.html'?new URL('index.html',self.registration.scope).href:url;}
const urls=ASSETS.map(asset=>assetKey(asset,assetRequest(asset)));
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const responses=await Promise.all(ASSETS.map(async asset=>{
   const url=assetRequest(asset);
   const response=await fetch(new Request(url,{cache:'reload',credentials:'same-origin'}));
   if(!response.ok||response.redirected||response.type==='opaque')throw Error('Asset unavailable '+asset+' status='+response.status+' redirected='+response.redirected);
   if(asset==='index.html'&&!(await response.clone().text()).includes('id="today-view"'))throw Error('Not the trainer');
   return [assetKey(asset,url),response];
 }));
 const cache=await caches.open(CACHE);await Promise.all(responses.map(([url,response])=>cache.put(url,response)));
 await self.skipWaiting();
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 for(const key of await caches.keys())if(key.startsWith('qazaq-offline-')&&key!==CACHE)await caches.delete(key);
 await self.clients.claim();
})()));
self.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('fetch',event=>{
 if(event.request.method!=='GET')return;
 const url=new URL(event.request.url),scope=new URL(self.registration.scope);
 if(url.pathname.includes('/api/'))return;
 if(url.origin!==scope.origin)return;
 const isHome=event.request.mode==='navigate'&&(url.pathname===scope.pathname||url.pathname===scope.pathname+'index.html');
 const key=isHome?new URL('index.html',scope).href:url.href;
 if(!isHome&&!urls.includes(key))return;
 event.respondWith((async()=>{
  const cache=await caches.open(CACHE);
  try{
    const fresh=await fetch(new Request(event.request,{cache:'reload',credentials:'same-origin'}));
    if(fresh.ok&&!fresh.redirected){await cache.put(key,fresh.clone());return fresh;}
  }catch{}
  return await cache.match(key)||fetch(event.request);
 })());
});
